import numpy as np
import time


def _ratio(h):
    h = np.asarray(h, dtype=float)
    if h.sum() <= 0:
        return -1.0
    g = np.convolve(h, h)
    mx = g.max()
    if mx <= 0:
        return -1.0
    L = np.empty(g.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = g
    Ls = L[:-1]
    Ln = L[1:]
    num = np.sum(Ls * Ls + Ls * Ln + Ln * Ln) / 3.0
    den = (h.sum() ** 2) * mx
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    rng = np.random.RandomState(1234)

    best_h = None
    best_r = -1.0

    def consider(h):
        nonlocal best_h, best_r
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.sum() <= 0:
            return
        r = _ratio(h)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            consider(s)

    # Analytic shapes that approximate the optimal (raised-cosine-like bump).
    def gauss(N, sigma):
        x = np.arange(N) - (N - 1) / 2.0
        return np.exp(-(x * x) / (2.0 * sigma * sigma))

    def cos_bump(N, p=1.0):
        x = np.linspace(-1, 1, N)
        return (np.cos(np.pi * x / 2.0) ** p) * (np.abs(x) < 1)

    Ns = [200, 300, 400, 500, 800, 1200]
    for N in Ns:
        for s in [N / 6.0, N / 5.0, N / 4.5, N / 4.0, N / 3.5]:
            consider(gauss(N, s))
        for p in [0.5, 1.0, 1.5, 2.0]:
            consider(cos_bump(N, p))
        if time.process_time() > deadline:
            break

    # Coordinate hill-climb: perturb one coordinate at a time with adaptive scale,
    # then do random restarts. This is far more sample efficient than one-at-a-time
    # random probes.
    def hill_climb(h0, max_time, scale0=0.15):
        h = h0.copy()
        h = h / h.max()
        cur_r = _ratio(h)
        N = h.size
        step = scale0
        while time.process_time() < max_time:
            improved = False
            # try a random permutation of coordinates
            for i in rng.permutation(N):
                old = h[i]
                # multiplicative + additive perturbation
                delta = (rng.rand() - 0.5) * 2.0 * step
                new = old * (1.0 + delta) + delta * step * 0.1
                if new < 0.0:
                    new = 0.0
                h[i] = new
                r = _ratio(h)
                if r > cur_r:
                    cur_r = r
                    improved = True
                else:
                    h[i] = old
                if time.process_time() > max_time:
                    break
            if not improved:
                step *= 0.55
                if step < 1e-4:
                    break
        return h, cur_r

    # Refine best shape at its native N
    if best_h is not None:
        h, r = hill_climb(best_h, deadline)
        consider(h)

    if best_h is None:
        return np.ones(50)
    h = best_h
    if h.sum() > 0:
        h = h / h.max()
    return h
